        /// <summary>返回该日期的节气名；非节气日或年份超出表范围则返回空字符串。</summary>
        public static string GetSolarTerm(DateTime date)
        {
            string[] row;
            if (!Data.TryGetValue(date.Year, out row))
            {
                return string.Empty;
            }
            string md = date.Month.ToString("00") + "-" + date.Day.ToString("00");
            for (int i = 0; i < row.Length; i++)
            {
                if (row[i] == md)
                {
                    return Names[i];
                }
            }
            return string.Empty;
        }
    }
